use PHPUnit\Framework\TestCase;

final class KbCalculatorTest extends TestCase
{
    public function testAddsTwoNumbers(): void
    {
        $this->assertSame(5, 2 + 3);
    }

    /** @dataProvider kbPriceCases */
    public function testTax(float $price, float $expected): void
    {
        $this->assertEqualsWithDelta($expected, $price * 1.18, 0.001);
    }

    public static function kbPriceCases(): array
    {
        return [[100.0, 118.0], [0.0, 0.0]];
    }
}

